import{_ as o,o as t,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-21（物理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-21-physics.md","filePath":"topics/physics/science-daily-2026-10-21-physics.md"}'),c={name:"topics/physics/science-daily-2026-10-21-physics.md"};function i(r,s,a,d,l,g){return t(),e("div",null,[...s[0]||(s[0]=[n('<h1 id="科学日报-·-2026-10-21-物理" tabindex="-1">科学日报 · 2026-10-21（物理） <a class="header-anchor" href="#科学日报-·-2026-10-21-物理" aria-label="Permalink to &quot;科学日报 · 2026-10-21（物理）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> — 第40期 ｜ 科学板块 落盘说明：文件名带 <code>-physics</code> 后缀以<strong>避免与其它主题同名文件互引产生伪边</strong>。</p></blockquote><hr><h2 id="科学日报-2026-10-21-液态水的「因果性」——涌现玻璃态动力学的新指纹" tabindex="-1">科学日报 2026-10-21：液态水的「因果性」——涌现玻璃态动力学的新指纹 <a class="header-anchor" href="#科学日报-2026-10-21-液态水的「因果性」——涌现玻璃态动力学的新指纹" aria-label="Permalink to &quot;科学日报 2026-10-21：液态水的「因果性」——涌现玻璃态动力学的新指纹&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-21.md</code> ｜ DOI: 10.1073/pnas.2616852123</p></blockquote><ul><li>痛点：分子液体（如水）中微观变量的<strong>延迟影响</strong>通常用<strong>时间关联函数</strong>探测；但这类函数在<strong>细致平衡下是对称的</strong>——因此**「看不见」动力学的方向性不对称**。</li><li>方法：改用<strong>因果推断度量</strong>，刻画集体变量之间的<strong>非对称耦合</strong>；分析常温 + 过冷水<strong>高密度液相（HDL）<strong>区的</strong>平衡分子动力学模拟</strong>。</li><li>结果：<strong>取向（转动）与平动自由度</strong>之间存在跨<strong>多个时空尺度</strong>的显著不对称： <ul><li><strong>室温</strong>：<strong>转动模式</strong>对平动有温和的<strong>方向性影响</strong>。</li><li><strong>过冷 HDL 区</strong>：<strong>平动运动反成动力学的主驱动</strong>。</li></ul></li><li>结论：<strong>「因果方向性的翻转」</strong> 可能是水<strong>涌现出玻璃态行为</strong>的一个标志。</li><li>洞察（对本库 <code>physics</code> 母题）：再次印证库内「<strong>换一个统计量，就换一个可见的世界</strong>」——相关函数（二阶、对称）看不到的东西，<strong>因果/有向度量</strong>能看到。与库内 10-20（位移电流散粒噪声：<strong>一次求平均丢失、看二阶矩才保留</strong>——均值走一路、方差走另一路）同构：<strong>同一个系统里，不同的矩/不同的度量承载不同的信息</strong>。对方法论的迁移：<strong>当「相关性为零」时，先问是不是度量本身把方向性抹掉了</strong>，而不是急着下「无因果」的结论。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ 第40期 科学板块</p></blockquote><p>关键词：液态水、causality、因果性、方向性不对称、时间关联函数、细致平衡、对称、因果推断度量、非对称耦合、取向自由度、转动、平动、高密度液相、HDL、过冷、玻璃态动力学、玻璃态、分子动力学模拟、多个时空尺度、主驱动翻转、涌现、二阶矩与有向度量</p><p>关联：<code>topics/physics/science-daily-2026-10-20.md</code>（位移电流散粒噪声：均值走一路、方差走另一路）、<code>topics/physics/index.md</code>（「换一个统计量就换一个可见的世界」）、<code>topics/physics/blind-men-measurement.md</code>（测量即选择）、<code>topics/quantum-physics/science-daily-2026-10-10.md</code></p>',10)])])}const y=o(c,[["render",i]]);export{h as __pageData,y as default};
